/// <remarks>
/// Pass one to <see cref="DbOptions.GetHistogramData(Histogram)"/>.
/// <para>
/// The values are positional in RocksDb's header, so they change between
/// releases when a counter is added or retired. They are generated from the
/// pinned version rather than written out by hand for that reason.
/// </para>
/// </remarks>
public enum Histogram
{
    /// <summary>
