    IoDispatcherAsyncReadPollWaitMicros = 68,

    /// <summary>
    /// Time (microseconds) from async read submission until the block consumer starts polling for completion.
    /// </summary>
    /// <remarks>RocksDb calls this <c>IO_DISPATCHER_ASYNC_READ_PREFETCH_LEAD_MICROS</c>.</remarks>
    IoDispatcherAsyncReadPrefetchLeadMicros = 69,

    /// <summary>
    /// Coefficient of variation of key gaps in blocks, scaled by 10000 (e.g., CV of 0.4532 is recorded as 4532). Currently only used by index blocks for uniform key distribution tracking.
    /// </summary>
    /// <remarks>RocksDb calls this <c>BLOCK_KEY_DISTRIBUTION_CV</c>.</remarks>
    BlockKeyDistributionCv = 70,

    /// <summary>
    /// Time (microseconds) in the &quot;prepare&quot; phase of an IngestExternalFile(s) call (validation and reading/linking the files; does not block writes). One sample per successful call; requires stats level &gt; kExceptTimers.
    /// </summary>
    /// <remarks>RocksDb calls this <c>INGEST_EXTERNAL_FILE_PREPARE_TIME</c>.</remarks>
    IngestExternalFilePrepareTime = 71,

    /// <summary>
    /// Time (microseconds) in the &quot;run&quot; phase of an IngestExternalFile(s) call (work under the DB mutex while writes are blocked). One sample per successful call; requires stats level &gt; kExceptTimers.
    /// </summary>
    /// <remarks>RocksDb calls this <c>INGEST_EXTERNAL_FILE_RUN_TIME</c>.</remarks>
    IngestExternalFileRunTime = 72,

    /// <summary>
    /// Time read requests spent waiting for rate limiter refills.
    /// </summary>
    /// <remarks>RocksDb calls this <c>RATE_LIMITER_WAIT_MICROS_READ</c>.</remarks>
    RateLimiterWaitMicrosRead = 73,

    /// <summary>
    /// Time write requests spent waiting for rate limiter refills.
    /// </summary>
    /// <remarks>RocksDb calls this <c>RATE_LIMITER_WAIT_MICROS_WRITE</c>.</remarks>
    RateLimiterWaitMicrosWrite = 74,

    /// <summary>
    /// Distribution of total memtable memory usage at flush start.
    /// </summary>
    /// <remarks>RocksDb calls this <c>FLUSH_MEMTABLE_MEMORY_BYTES</c>.</remarks>
    FlushMemtableMemoryBytes = 75,

    /// <summary>
    /// Distribution of total memtable data size at flush start.
    /// </summary>
    /// <remarks>RocksDb calls this <c>FLUSH_MEMTABLE_TOTAL_DATA_SIZE</c>.</remarks>
    FlushMemtableTotalDataSize = 76,

    /// <summary>
    /// Distribution of total memtable memory usage for write-buffer-full flushes.
    /// </summary>
    /// <remarks>RocksDb calls this <c>FLUSH_WRITE_BUFFER_FULL_MEMTABLE_MEMORY_BYTES</c>.</remarks>
    FlushWriteBufferFullMemtableMemoryBytes = 77,

    /// <summary>
    /// Distribution of total memtable memory usage for WBM-triggered flushes.
    /// </summary>
    /// <remarks>RocksDb calls this <c>FLUSH_WRITE_BUFFER_MANAGER_MEMTABLE_MEMORY_BYTES</c>.</remarks>
    FlushWriteBufferManagerMemtableMemoryBytes = 78,

    /// <summary>
    /// Time spent opening the secondary DB inside DB::OpenAndCompact().
    /// </summary>
    /// <remarks>RocksDb calls this <c>OPEN_AND_COMPACT_DB_OPEN_MICROS</c>.</remarks>
    OpenAndCompactDbOpenMicros = 79,
